# Sample listings (Mitra, 2026-11-24, option 1): 28 sample sellers, one per main category, 10 listings each.
# Labelled as samples everywhere: the store name ends "(Sample)", every listing name starts "Sample ·", and every
# description opens with the notice below. No phone, GSTIN, PAN or verified badge on any sample seller.
#
# Item tuple: (sub-category name or None for the main category itself, picture "<group>/<slug>", name, price ₹,
#              moq, unit, extra columns dict, detail sentence)
# Pictures are Cosora's own category pictures (src/assets/categories/tiles/<group>/<slug>.jpg).

NOTICE = ("Sample listing: this shows how a listing looks on Cosora. It isn't for sale, "
          "and its seller can't be contacted.")

SIZES = ["S", "M", "L", "XL", "XXL"]
KID_SIZES = ["2-3Y", "4-5Y", "6-7Y", "8-9Y", "10-11Y"]
WAIST = ["28", "30", "32", "34", "36"]

def ap(fabric, gsm=None, colour=None, gender=None, fit=None, sizes=SIZES, **kw):
    d = {"fabric": fabric, "colour": colour, "gender": gender, "fit_type": fit, "sizes": sizes,
         "country_of_origin": "India", "customization_available": True}
    if gsm: d["gsm"] = gsm
    d.update(kw)
    return d

def goods(**kw):
    d = {"country_of_origin": "India", "customization_available": kw.pop("custom", True)}
    d.update(kw)
    return d

